import { GameScene } from "../GameScene";

export class Raycaster {
  constructor(scene: GameScene) {
    const raycaster = scene.raycasterPlugin.createRaycaster();
    const ray = raycaster.createRay();

    const rectangle = scene.add
      .rectangle(100, 100, 50, 50)
      .setStrokeStyle(1, 0xff0000);

    //map game object
    raycaster.mapGameObjects(rectangle);

    //create group
    const group = scene.add.group();

    //map game objects actually in group
    raycaster.mapGameObjects(group.getChildren());

    // //map tilemap layer
    // const map = this.make.tilemap();
    // this.tilemap = this.map.createStaticLayer();
    raycaster.mapGameObjects(scene.tilemap, false, {
      collisionTiles: [1, 2, 3], //array of tiles types which can collide with ray
    });
  }
}
